/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `ValidateRoadDistance` BEFORE INSERT ON `road_segment` FOR EACH ROW BEGIN
    IF NEW.Distance_km < 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Road distance cannot be negative';
    END IF;
END */;;
