/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `ValidateRouteDistance` BEFORE INSERT ON `route` FOR EACH ROW BEGIN
    IF NEW.TotalDistance < 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Route distance cannot be negative';
    END IF;
END */;;
