DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `CalculateAverageRoadDistance`()
BEGIN
    DECLARE done INT DEFAULT 0;
    DECLARE road_distance DECIMAL(10,3);
    DECLARE total_distance DECIMAL(15,3) DEFAULT 0;
    DECLARE road_count INT DEFAULT 0;

    DECLARE road_cursor CURSOR FOR
        SELECT Distance_km
        FROM ROAD_SEGMENT
        WHERE Distance_km IS NOT NULL;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

    OPEN road_cursor;

    read_loop: LOOP

        FETCH road_cursor INTO road_distance;

        IF done = 1 THEN
            LEAVE read_loop;
        END IF;

        SET total_distance = total_distance + road_distance;
        SET road_count = road_count + 1;

    END LOOP;

    CLOSE road_cursor;

    SELECT
        ROUND(total_distance / road_count, 3)
        AS AverageRoadDistance;

END ;;
DELIMITER ;
