CREATE DEFINER=`root`@`localhost` PROCEDURE `GetRouteDetails`(
    IN sourceCity INT,
    IN destinationCity INT
)
BEGIN
    SELECT
        R.RouteID,
        SC.CityName AS SourceCity,
        DC.CityName AS DestinationCity,
        R.TotalDistance,
        R.EstimatedTime,
        R.SafetyScore
    FROM ROUTE R
    JOIN CITY SC
        ON R.SourceCityID = SC.CityID
    JOIN CITY DC
        ON R.DestinationCityID = DC.CityID
    WHERE R.SourceCityID = sourceCity
      AND R.DestinationCityID = destinationCity;
END ;;
DELIMITER ;
