CREATE DEFINER=`root`@`localhost` PROCEDURE `GetShortRoutes`(
    IN maxDistance DECIMAL(10,3)
)
BEGIN
    SELECT
        R.RouteID,
        SC.CityName AS SourceCity,
        DC.CityName AS DestinationCity,
        R.TotalDistance,
        R.EstimatedTime
    FROM ROUTE R
    JOIN CITY SC
        ON R.SourceCityID = SC.CityID
    JOIN CITY DC
        ON R.DestinationCityID = DC.CityID
    WHERE R.TotalDistance <= maxDistance
    ORDER BY R.TotalDistance;
END ;;
DELIMITER ;
